INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bee9bcec-b493-48d8-bf5b-8ab8189fe025', 'a1b2c3d4-2222-4000-8000-000000000002', 5, 'Oração de Intercessão', 'Rezar pelos outros como Jesus reza por nós', '{"intro": "Jesus vive para interceder por n\u00f3s (Hb 7,25). Quando rezamos pelos outros, participamos da miss\u00e3o sacerdotal de Cristo. A intercess\u00e3o n\u00e3o \u00e9 informar Deus sobre problemas \u2014 Ele j\u00e1 sabe. \u00c9 unir nosso cora\u00e7\u00e3o ao Dele, carregando juntos o peso do mundo. Santos como Padre Pio recebiam milhares de inten\u00e7\u00f5es e as levavam ao altar. Cada intercess\u00e3o \u00e9 um ato de amor concreto.", "prayer": "Senhor, coloco diante de Ti todos aqueles que carrego no cora\u00e7\u00e3o. Cura, liberta, consola e transforma pela Tua miseric\u00f3rdia. Am\u00e9m.", "practice": "Fa\u00e7a uma lista de 5 pessoas que precisam de ora\u00e7\u00e3o. Reserve 2 minutos para cada uma. Apresente-as a Deus com amor, n\u00e3o com ansiedade.", "scripture": "\"Eu vos digo: Pedi e vos ser\u00e1 dado; buscai e achareis; batei e vos ser\u00e1 aberto.\" \u2014 Lc 11,9", "reflection": "Por quem voc\u00ea sente que Deus est\u00e1 pedindo que reze? H\u00e1 algu\u00e9m que precisa das suas ora\u00e7\u00f5es agora?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;